-- GUS-242 step 1e — traditions.
--
-- The Tier-2 tradition vocabulary: 400-600 regional, ethnic and
-- religious culinary traditions, each with a definition AND a source.
--
-- Source: Wikidata items that are instances of 'cuisine' (Q1778821)
-- and carry a country. Wikidata content is CC0. The Q-id is recorded
-- as the source.
--
-- The 40 traditions that already existed keep their rows; the ones
-- Wikidata does not model get a project-written definition with the
-- source recorded as 'gustale:1e', so the source column never points
-- at a page that does not exist.
--
-- Generated by scripts/curate_traditions_1e.py +
-- scripts/emit_traditions_1e_sql.py
--
-- Run inside a transaction with the count assertions FIRST (RULES.md §3).
--
-- Usage:
--   psql -v ON_ERROR_STOP=1 -d <db> -f packages/db/drizzle/0019_gus242_traditions_1e.sql

\set ON_ERROR_STOP on
-- IDEMPOTENT
--
-- Safe to re-apply: the guard checks that the data is present AND
-- that this migration has not already been applied.
--
-- The "already applied" marker for 0019: the new traditions are
-- present AND every existing one carries a definition and a source.
SELECT
  EXISTS (SELECT 1 FROM dish_traditions)
  AND NOT (
    (SELECT count(*) FROM dish_traditions
      WHERE slug IN ('abruzzese-cuisine','acadian-cuisine','acehnese-cuisine',
                     'afghan-cuisine','albanian-cuisine','andalusian-cuisine',
                     'alsatian-cuisine','andean-cuisine','andhra-cuisine',
                     'angolan-cuisine','anguillan-cuisine')) = 10
    AND
    (SELECT count(*) FROM dish_traditions
      WHERE definition IS NULL OR source IS NULL) = 0
  ) AS have_data \gset
\if :have_data
\echo 'GUS-242: the seeded data is present and this migration is not yet applied - running it'


BEGIN;

